package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"strings"
	"time"

	_ "modernc.org/sqlite" // the pure-Go SQLite driver
)

// The columns of an instant are TEXT in the UTC layout below: database/sql
// would otherwise scan a TEXT timestamp into time.Time and reject it, so
// every read takes a string and parses it.
const timeLayout = "2006-01-02T15:04:05.999999999Z"

func parseTime(value, what string) (time.Time, error) {
	t, err := time.Parse(timeLayout, value)
	if err != nil {
		return time.Time{}, fmt.Errorf("store: %s %q: %w", what, value, err)
	}
	return t.UTC(), nil
}

// SQLiteStore is Store over one SQLite database file.
type SQLiteStore struct {
	db *sql.DB
}

var _ Store = (*SQLiteStore)(nil)

// Open prepares $dataDir/links.db and applies the embedded migrations. The
// database serialises writes, so one connection serves the app.
func Open(dataDir string) (*SQLiteStore, error) {
	if dataDir == "" {
		return nil, errors.New("store: DataDir is empty")
	}
	path := filepath.Join(dataDir, "links.db")
	dsn := "file:" + path + "?_pragma=journal_mode(WAL)&_pragma=busy_timeout(10000)&_pragma=foreign_keys(1)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("store: open %s: %w", path, err)
	}
	db.SetMaxOpenConns(1)
	if err := db.Ping(); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("store: open %s: %w", path, err)
	}
	s := &SQLiteStore{db: db}
	if err := s.migrate(context.Background()); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

